package org.kanger.storage.dumb2;
import java.nio.file.*;import java.util.*;import org.kanger.*;import org.kanger.exception.*;import org.kanger.enums.StorageLifecycleErrorCode;
public final class ContextSignedEligibilityLiveRunner {
 static int checks;static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("signed-eligibility-live-");System.setProperty("user.home",d.toString());ContextNativeCandidateLeaseMatrix.create(d,"A","!$u seed(u)&&~blocked(u);");try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"physical parent");f.db.connectContext("A");ContextSignedCandidateInspection.Limits l=ContextSignedCandidateLeaseMatrix.limits();long revision=f.db.getRevision();String fp=ContextNativePendingInspectionMatrix.inventory(f,f.mind).fingerprint;Mind child=new Mind(f.mind);try{require(child.compile("!@u seed(u)->~blocked(u);",null,false),"actual quiescent whole child");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){require(lease.qualifySigned(l).status==ContextSignedPendingGuard.Status.SCOPED_QUIESCENT,"current signed native gate ALREADY passes");String reason=null;try{lease.inspectWitness(8,16,64000000,500000);}catch(IllegalStateException e){reason=e.getMessage();}require("Pending witness family incomplete: Positive private witness bundle required".equals(reason),"exact live selector WITNESS assembly barrier, before family evaluation/model");lease.requireCurrent();}ContextSignedCommitException no=null;try{f.db.validatePendingSignedProductionCommit(child,l,64000000,64000000,1000000);}catch(ContextSignedCommitException e){no=e;}require(no!=null&&no.getPhase().equals("full-family-qualification")&&no.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&no.getSignedEvidence()==null,"current owning boundary fails CLOSED at full family, not old whole-row gate");require(no.getCause() instanceof IllegalStateException&&"Pending witness family incomplete: Positive private witness bundle required".equals(no.getCause().getMessage()),"exact original family guard cause preserved");}finally{f.mind.release(child);}require(f.db.getRevision()==revision&&ContextNativePendingInspectionMatrix.inventory(f,f.mind).fingerprint.equals(fp),"physical parent unchanged");}System.out.println("SIGNED_ELIGIBILITY_LIVE currentSignedPassThenFamilyAssemblyIncomplete=true exactCauseNotEarlierRowGate=true noGuardRemoved=true");System.out.println("CONTEXT_SIGNED_ELIGIBILITY_LIVE_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
